var t=[{title:`Bereid voor voordat je de stang belast`,text:`Controleer of de bank, het rek, de stang, de klemmen en de vloer geschikt zijn voor de oefening. In een squatrek vangen veiligheidspinnen of -banden op de juiste hoogte de stang op als je er niet mee kunt opstaan. Train je alleen, probeer dan geen bankdrukken in de buurt van je maximum zonder beveiliging.`},{title:`Wat een spotter doet`,text:`Spreek vóór een barbell-bankdruk met je spotter af of je een aanreiking wilt, wanneer hij moet beginnen te helpen en welke commando’s je gebruikt. Een spotter moet kunnen helpen en mag je niet afleiden. Eén onervaren spotter kan je veiligheid onder een zeer zwaar gewicht niet garanderen.`},{title:`Loslaten hangt af van de uitrusting`,text:`Gewichthefplatforms en bumperplates zijn gemaakt voor bepaalde beheerste worpen. Vloeren thuis, drukke sportscholen en verstelbare dumbbells zijn dat misschien niet. Oefen nooit geïmproviseerde noodlossingen in de buurt van mensen of breekbare apparatuur. Leer de ontsnappingsmethode voor jouw uitrusting van een gekwalificeerde instructeur voordat je zware lifts probeert.`},{title:`Verminder de behoefte aan redding`,text:`Laat herhalingen in reserve, kies een gewicht dat je kunt beheersen en gebruik een machine- of dumbbellversie als die beter bij je opstelling past. Je hoeft niet tot spierfalen te trainen om vooruit te gaan, vooral niet bij complexe lifts.`},{title:`TrainUp gebruiken`,text:`TrainUp gaat er niet van uit dat je een spotter, een rek of een veilige plek hebt om gewichten te laten vallen. Het schema kiest alleen oefeningen die passen bij de uitrusting en ruimte die je in Profiel instelt, dus houd die instellingen nauwkeurig. Het schrijft ook geen gewichten voor: jij kiest het gewicht.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktische richtlijnen van het ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};